ALTER TABLE "illustration_requests" ADD COLUMN "reference_details" JSONB;
CREATE TABLE "illustration_wallets" ("id" TEXT PRIMARY KEY,"invitation_id" TEXT NOT NULL UNIQUE,"granted" INTEGER NOT NULL DEFAULT 0,"remaining" INTEGER NOT NULL DEFAULT 0,CONSTRAINT "illustration_wallets_invitation_id_fkey" FOREIGN KEY ("invitation_id") REFERENCES "invitations"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE "illustration_generations" ("id" TEXT PRIMARY KEY,"invitation_id" TEXT NOT NULL,"request_key" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'queued',"reference_urls" JSONB NOT NULL,"style_version" TEXT NOT NULL,"result_url" TEXT,"aspect" DOUBLE PRECISION,"error" TEXT,"refunded" BOOLEAN NOT NULL DEFAULT false,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL,CONSTRAINT "illustration_generations_invitation_id_fkey" FOREIGN KEY ("invitation_id") REFERENCES "invitations"("id") ON DELETE CASCADE ON UPDATE CASCADE);
CREATE UNIQUE INDEX "illustration_generations_invitation_id_request_key_key" ON "illustration_generations"("invitation_id","request_key");
CREATE INDEX "illustration_generations_status_created_at_idx" ON "illustration_generations"("status","created_at");
